'use strict';

// MODULES //

var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var format = require( '@stdlib/string/format' );
var ndarray = require( './ndarray.js' );


// MAIN //

/**
* Generates a double-precision floating-point Vandermonde matrix.
*
* @param {string} order - storage layout
* @param {NonNegativeInteger} M - number of rows in the matrix `Out`
* @param {NonNegativeInteger} N - number of columns in the matrix `Out`
* @param {number} mode - specifies whether columns should contain powers that are increasing (`1`) or decreasing (`-1`)
* @param {Float64Array} x - input vector
* @param {integer} strideX - stride length for `x`
* @param {Float64Array} out - output matrix
* @param {PositiveInteger} LDO - stride of the first dimension of `Out` (a.k.a., leading dimension of the matrix `Out`)
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} second argument must be a nonnegative integer
* @throws {RangeError} third argument must be a nonnegative integer
* @throws {RangeError} sixth argument must be non-zero
* @throws {RangeError} eighth argument must be a valid stride
* @returns {Float64Array} output matrix
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float64Array( 9 );
*
* dvander( 'row-major', 3, 3, -1, x, 1, out, 3 );
* // out => <Float64Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*/
function dvander( order, M, N, mode, x, strideX, out, LDO ) {
	var iscm;
	var vala;
	var sa1;
	var sa2;
	var ox;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}

	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Second argument must be a nonnegative integer. Value: `%d`.', M ) );
	}

	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Third argument must be a nonnegative integer. Value: `%d`.', N ) );
	}

	if ( strideX === 0 ) {
		throw new RangeError( format( 'invalid argument. Sixth argument must be non-zero. Value: `%d`.', strideX ) );
	}

	// Check if we can early return...
	if ( M === 0 || N === 0 ) {
		return out;
	}

	iscm = isColumnMajor( order );
	if ( iscm ) {
		vala = M;
	} else {
		vala = N;
	}

	if ( LDO < vala ) {
		throw new RangeError( format( 'invalid argument. Eighth argument must be greater than or equal to %d. Value: `%d`.', vala, LDO ) );
	}

	ox = stride2offset( M, strideX );
	if ( iscm ) {
		sa1 = 1;
		sa2 = LDO;
	} else { // order === 'row-major'
		sa1 = LDO;
		sa2 = 1;
	}
	return ndarray( M, N, mode, x, strideX, ox, out, sa1, sa2, 0 );
}


// EXPORTS //

module.exports = dvander;
